class Solution:
    def kInversePairs(self, n: int, k: int) -> int:
        MOD = 10**9 + 7
        dp = [1] + [0] * k

        for i in range(1, n + 1):
            new_dp = [0] * (k + 1)
            new_dp[0] = 1
            for j in range(1, k + 1):
                val = (new_dp[j - 1] + dp[j] - (dp[j - i] if j >= i else 0)) % MOD
                new_dp[j] = (val + MOD) % MOD
            dp = new_dp

        return dp[k]

class Solution {
public:
    int kInversePairs(int n, int k) {
        const int MOD = 1e9 + 7;
        vector<int> dp(k + 1, 0);
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            vector<int> newDp(k + 1, 0);
            newDp[0] = 1;
            for (int j = 1; j <= k; j++) {
                long long val = (long long)newDp[j - 1] + dp[j] - (j >= i ? dp[j - i] : 0);
                newDp[j] = (val % MOD + MOD) % MOD;
            }
            dp = move(newDp);
        }
        return dp[k];
    }
};

