        for (int i = 1; i <= n; i++) {
            int[] newDp = new int[k + 1];
            newDp[0] = 1;
            for (int j = 1; j <= k; j++) {
                long val = (long) newDp[j - 1] + dp[j] - (j >= i ? dp[j - i] : 0);
                newDp[j] = (int) ((val % MOD + MOD) % MOD);
            }
            dp = newDp;
